import 'package:flutter/material.dart';import '../../core/widgets/zaylo_widgets.dart';import '../../services/ai_service.dart';
class AiScreen extends StatefulWidget{const AiScreen({super.key});@override State<AiScreen> createState()=>_AiScreenState();}class _AiScreenState extends State<AiScreen>{final c=TextEditingController();final service=MockAiService();final messages=<String>['Hi, I’m Zaylo AI. Ask me about budgets, groceries, jobs, studies or farming.'];void send([String? text]){final q=text??c.text;if(q.trim().isEmpty)return;setState(()=>messages.add('You: $q'));c.clear();service.reply(q).then((r)=>setState(()=>messages.add('Zaylo AI: $r')));}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Zaylo AI'),actions:[TextButton(onPressed:()=>setState(()=>messages.clear()),child:const Text('Clear'))]),body:Column(children:[Wrap(spacing:8,children:['Create a weekly budget','Find affordable groceries','Explain today’s exchange rates','Help me prepare for an exam','Show farming advice','Find jobs near me'].map((p)=>ActionChip(label:Text(p),onPressed:()=>send(p))).toList()),Expanded(child:ListView(padding:const EdgeInsets.all(16),children:[for(final m in messages) Align(alignment:m.startsWith('You:')?Alignment.centerRight:Alignment.centerLeft,child:ZayloCard(child:Text(m))) ])),Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:TextField(controller:c,decoration:const InputDecoration(hintText:'Ask Zaylo AI'))),IconButton(onPressed:send,icon:const Icon(Icons.send),tooltip:'Send')]))]));}
